"""
    Format a dictionary of dictionaries in string format in the "custom attribute" syntax
    e.g. custom="readingOrder {index:1;} structure {type:heading;}"
    """
def format_custom_attr(ddic: Any) -> object {
    s = "";
    for (k1, d2) in ddic.items() {
        if s {
            s += " ";
        }
        s += "%s" % k1;
        s2 = "";
        for (k2, v2) in d2.items() {
            if s2 {
                s2 += " ";
            }
            s2 += "%s:%s;" % (k2, v2);
        }
        s += " {%s}" % s2;
    }
    return s;
}

"""Symmetrically extend the range given by the `min_max` pair.
       The new range will be 1 + `extend_ratio` larger than the original range.
    """
def extend_range(min_max: Any, extend_ratio: Any = 0.2) -> object {
    mme = ((min_max[1] - min_max[0]) * extend_ratio) / 2;
    return ((min_max[0] - mme), (min_max[1] + mme));
}

